import { command, getPlayer, safeReply } from "#utils/RythmCommands";
const presets={clear:{},nightcore:{timescale:{speed:1.25,pitch:1.15,rate:1}},vaporwave:{timescale:{speed:0.8,pitch:0.8,rate:1}},slow:{timescale:{speed:0.7,pitch:1,rate:1}},bass:{equalizer:Array.from({length:15},(_,band)=>({band,gain:band<6?0.22:0}))}};
const run=async x=>{const p=getPlayer(x),name=(x.interaction?.options?.getString("preset")||x.args?.[0]||"clear").toLowerCase();if(!p?.currentTrack)return safeReply(x,"🎚️ Effects","Nothing is playing.",0xED4245);const filter=presets[name];if(!filter)return safeReply(x,"🎚️ Effects","Presets: clear, nightcore, vaporwave, slow, bass.",0xED4245);if(typeof p.player.setFilters!=="function")return safeReply(x,"🎚️ Effects","This Lavalink node does not expose audio filters.",0xED4245);await p.player.setFilters(filter);return safeReply(x,"🎚️ Effects",name==="clear"?"All effects cleared.":"Applied **"+name+"**.");};
export default command({name:"effects",description:"Apply music effects",aliases:["effect","filter"],options:[{name:"preset",description:"Effect preset",type:3,required:false,choices:Object.keys(presets).map(v=>({name:v,value:v}))}],dj:true,voiceRequired:true,execute:run,slashExecute:run});